// tb/v3/tb_ch09_calc.v
// Cycle-accurate, bit-exact frame-level testbench for rtl/v3/ch09_f0_calc.v
// Compatible with iverilog -g2012 -Wall
//
// Verification protocol:
// - Reads streaming lag vectors generated by Python twin from golden_v2 synthetic frames
// - Verifies peak detection, candidate argmax Sc tracking, s2 shift,
//   and F0_Q12.4 single division on multiple frames (voiced, unvoiced, glide).
// - 2-phase sampling convention:
//     * Inputs driven at @(negedge clk)
//     * Registered outputs checked at @(posedge clk); #1
// - Strict loop condition, counts all errors, reports total

`timescale 1ns/1ps

module tb_ch09_calc;

    localparam integer EXPECTED_CYCLES = 2593;

    // Clock generation (50 MHz, 20 ns period)
    reg clk = 0;
    always #10 clk = ~clk;

    // DUT signals
    reg               rst_n;
    reg               in_valid;
    reg  [7:0]        in_tau;
    reg  signed [27:0] in_U;
    reg  signed [27:0] in_Sc;
    reg  [26:0]       in_R0n;
    reg               in_last;

    wire              out_valid;
    wire [15:0]       out_f0_raw;
    wire [7:0]        out_best_tau;
    wire signed [27:0] out_sc;
    wire [26:0]       out_r0n;
    wire              out_found;

    // Instantiate DUT
    ch09_f0_calc dut (
        .clk          (clk),
        .rst_n        (rst_n),
        .in_valid     (in_valid),
        .in_tau       (in_tau),
        .in_U         (in_U),
        .in_Sc        (in_Sc),
        .in_R0n       (in_R0n),
        .in_last      (in_last),
        .out_valid    (out_valid),
        .out_f0_raw   (out_f0_raw),
        .out_best_tau (out_best_tau),
        .out_sc       (out_sc),
        .out_r0n      (out_r0n),
        .out_found    (out_found)
    );

    // Testbench tracking variables
    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus record variables
    integer stim_rst_n;
    integer stim_in_vld;
    integer stim_in_tau;
    reg signed [63:0] stim_in_U;
    reg signed [63:0] stim_in_Sc;
    integer stim_in_R0n;
    integer stim_in_last;

    // Expected record variables
    integer exp_out_vld;
    integer exp_out_f0q;
    integer exp_out_tau;
    reg signed [63:0] exp_out_sc;
    integer exp_out_r0n;
    integer exp_out_found;

    initial begin
        rst_n     = 0;
        in_valid  = 0;
        in_tau    = 8'd0;
        in_U      = 28'sd0;
        in_Sc     = 28'sd0;
        in_R0n    = 27'd0;
        in_last   = 0;
        cycle_idx = 0;
        errors    = 0;

        stim_fd = $fopen("verify_v3/tb_ch09_calc_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch09_calc_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch09_calc_stim.txt");
            $finish;
        end

        exp_fd = $fopen("verify_v3/tb_ch09_calc_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch09_calc_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch09_calc_expected.txt");
            $finish;
        end

        $display("=== STARTING CH09 FULL-CORE FRAME CALC VERIFICATION ===");

        @(negedge clk);

        while ($fscanf(stim_fd, "%d %d %d %d %d %d %d\n",
                       stim_rst_n, stim_in_vld, stim_in_tau,
                       stim_in_U, stim_in_Sc, stim_in_R0n, stim_in_last) == 7 &&
               $fscanf(exp_fd, "%d %d %d %d %d %d\n",
                       exp_out_vld, exp_out_f0q, exp_out_tau,
                       exp_out_sc, exp_out_r0n, exp_out_found) == 6) begin

            // 1. Drive inputs during clock low phase
            rst_n    = (stim_rst_n != 0) ? 1'b1 : 1'b0;
            in_valid = (stim_in_vld != 0) ? 1'b1 : 1'b0;
            in_tau   = stim_in_tau[7:0];
            in_U     = stim_in_U[27:0];
            in_Sc    = stim_in_Sc[27:0];
            in_R0n   = stim_in_R0n[26:0];
            in_last  = (stim_in_last != 0) ? 1'b1 : 1'b0;

            // 2. Wait for rising edge and sample registered outputs after #1
            @(posedge clk);
            #1;

            if (out_valid !== ((exp_out_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: out_valid mismatch DUT=%b EXP=%b",
                         cycle_idx, out_valid, exp_out_vld != 0);
                errors = errors + 1;
            end

            if (out_valid) begin
                if (out_f0_raw !== exp_out_f0q[15:0]) begin
                    $display("[FAIL] Cycle %0d: out_f0_raw mismatch DUT=%0d EXP=%0d",
                             cycle_idx, out_f0_raw, exp_out_f0q);
                    errors = errors + 1;
                end

                if (out_best_tau !== exp_out_tau[7:0]) begin
                    $display("[FAIL] Cycle %0d: out_best_tau mismatch DUT=%0d EXP=%0d",
                             cycle_idx, out_best_tau, exp_out_tau);
                    errors = errors + 1;
                end

                if (out_sc !== exp_out_sc[27:0]) begin
                    $display("[FAIL] Cycle %0d: out_sc mismatch DUT=%0d EXP=%0d",
                             cycle_idx, $signed(out_sc), $signed(exp_out_sc));
                    errors = errors + 1;
                end

                if (out_r0n !== exp_out_r0n[26:0]) begin
                    $display("[FAIL] Cycle %0d: out_r0n mismatch DUT=%0d EXP=%0d",
                             cycle_idx, out_r0n, exp_out_r0n);
                    errors = errors + 1;
                end

                if (out_found !== ((exp_out_found != 0) ? 1'b1 : 1'b0)) begin
                    $display("[FAIL] Cycle %0d: out_found mismatch DUT=%b EXP=%b",
                             cycle_idx, out_found, exp_out_found != 0);
                    errors = errors + 1;
                end
            end

            cycle_idx = cycle_idx + 1;
            @(negedge clk);
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        if (cycle_idx != EXPECTED_CYCLES) begin
            $display("[FAIL] Read %0d cycles, expected %0d", cycle_idx, EXPECTED_CYCLES);
            errors = errors + 1;
        end

        $display("=== Total comparison errors: %0d ===", errors);
        if (errors == 0) begin
            $display("=== ALL %0d VECTORS MATCHED SUCCESSFULLY ===", cycle_idx);
        end else begin
            $display("=== [FAIL] VERIFICATION FAILED WITH %0d ERRORS ===", errors);
        end

        $finish;
    end

endmodule
